package de.lautstark.zeigmal.ui

import androidx.compose.ui.graphics.Color

/**
 * The few colours the adult mode needs, ported from Lautstark/design's dark
 * scheme for zeigmal's accent #00A88E. The child mode is black and the mark,
 * and takes nothing from here. A generated file may not carry a version, so
 * this names its source and its input, as vorlaut-app's port does.
 */
object Palette {
    val accent = Color(0xFF00A88E)
    val accentStrong = Color(0xFF3FD1B4)
    val accentSoft = Color(0xFF0E3A33)
    val bg = Color(0xFF151817)
    val surface = Color(0xFF1E2221)
    val surface2 = Color(0xFF283030)
    val line = Color(0xFF3A4241)
    val text = Color(0xFFE6E9E8)
    val textDim = Color(0xFFA7ADAB)
    val textFaint = Color(0xFF6F7674)
    val danger = Color(0xFFFF8A80)
}
